<!DOCTYPE html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>PAY-{{ str_pad((string)$payment->id,8,'0',STR_PAD_LEFT) }}</title><style>body{font:14px/1.6 Arial,sans-serif;background:#eee;margin:0;color:#111}.receipt{max-width:720px;margin:24px auto;background:#fff;padding:32px;overflow-wrap:anywhere}h1{font-size:24px}.row{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #ddd;padding:10px 0}.toolbar{max-width:720px;margin:20px auto}.toolbar button,.toolbar a{padding:10px;display:inline-block}small{color:#555}@media(max-width:600px){.receipt{padding:18px;margin:12px}.toolbar{margin:12px}}@media print{@page{size:A4;margin:15mm}body{background:#fff}.toolbar{display:none}.receipt{max-width:none;margin:0;padding:0}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button><a href="{{ route('admin.orders.due-collection',$order) }}">Back to Collections</a></div><main class="receipt">@if ($company->logo)<img src="{{ asset($company->logo) }}" alt="{{ $company->name }}" style="max-width:140px;max-height:60px;object-fit:contain">@endif<h1>{{ $company->name ?: config('app.name') }}</h1><p>{{ $company->address }}<br>{{ $company->hotline ?: $company->phone }}</p><h2>Payment Receipt</h2><div class="row"><strong>Receipt</strong><span>PAY-{{ str_pad((string)$payment->id,8,'0',STR_PAD_LEFT) }}</span></div><div class="row"><span>Order Invoice</span><strong>{{ $order->order_no }}</strong></div><div class="row"><span>Customer</span><span>{{ $order->customerInfo?->name ?? $order->customer?->name }}<br>{{ $order->customerInfo?->phone ?? $order->customer?->mobile }}</span></div><div class="row"><span>Received At</span><span>{{ $payment->received_at?->timezone('Asia/Dhaka')->format('d M Y h:i A') }}</span></div><div class="row"><span>Payment Method</span><strong>{{ $payment->payment_method }}</strong></div><div class="row"><span>Transaction Reference</span><span>{{ $payment->transaction_id ?: 'Cash receipt' }}</span></div><div class="row"><strong>Amount Received</strong><strong>BDT {{ number_format((float)$payment->amount,2) }}</strong></div><div class="row"><span>Paid Balance After</span><span>BDT {{ number_format((float)$payment->paid_after,2) }}</span></div><div class="row"><strong>Due After This Receipt</strong><strong>BDT {{ number_format((float)$payment->due_after,2) }}</strong></div><div class="row"><span>Received By</span><span>{{ $payment->collector?->name ?: 'Admin' }}</span></div>@if ($payment->note)<p style="white-space:pre-line">Note: {{ $payment->note }}</p>@endif<p><small>Balances show the state when this receipt was issued. Later receipts may change the current balance.</small></p><p style="margin-top:40px">Authorized signature: ____________________</p></main></body></html>
